{"file_path":"src/address.js","content":"/**
 * Cell-address parsing and ordering. An address is one or two letters (a
 * column, A-Z then AA-ZZ) followed by one to three digits (a row, at least
 * 1). Any 1-2 letter combination and any 1-3 digit combination already fall
 * inside those bounds, so validity only needs the shape check plus row >= 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Column letters (A, B, ..., Z, AA, ...) to a 1-based column number. */
export function columnToNumber(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** A 1-based column number back to its letters. */
export function numberToColumn(n) {
  let letters = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    n = Math.floor((n - 1) / 26)
  }
  return letters
}

/**
 * Parses a raw token as a cell address. Returns null when the token is not
 * shaped like an address, or names a row of 0 - either way, "outside the
 * addressable range" for formula purposes.
 */
export function parseAddress(raw) {
  const m = ADDRESS_RE.exec(raw)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = columnToNumber(m[1])
  return { col, row }
}

export function formatAddress(col, row) {
  return numberToColumn(col) + String(row)
}

/** Ascending column order, then ascending row order within a column. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

