{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['+', '-', '*', '/', '^', '(', ')', ',', ':', '=', '<', '>']

/**
 * Splits a formula body into tokens. Returns null when a character does not
 * belong to any token, which makes the whole formula a grammar failure.
 */
export function lex(text) {
  const tokens = []
  let i = 0
  while (i < text.length) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(text.slice(i))
      tokens.push({ kind: 'num', text: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(text.slice(i))
      tokens.push({ kind: 'word', text: m[0] })
      i += m[0].length
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ kind: 'op', text: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ kind: 'op', text: ch })
      i += 1
      continue
    }
    return null
  }
  return tokens
}
"}

