{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for a formula body, built on top of the token
 * list from lexer.js. Precedence, loosest to tightest: comparisons, then `+`
 * `-`, then `*` `/`, then `^` (right-associative), then a leading sign
 * (tighter than `^`).
 *
 * A range (`A1:B3`) parses at the same primary level as a bare address, in
 * any position the grammar allows an expression - whether that use is
 * "directly a function argument" is decided later, by the evaluator, from
 * where the resulting node sits in the tree.
 */

const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseError extends Error {}

/** Parses a formula body. Returns null when the grammar rejects it. */
export function parseFormula(text) {
  const tokens = lexOrThrow(text)
  if (tokens === null) return null
  const state = { tokens, pos: 0 }
  try {
    const node = parseComparison(state)
    if (state.pos !== tokens.length) throw new ParseError('trailing tokens')
    return node
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}

function lexOrThrow(text) {
  // Re-exported indirection kept local so this module owns error handling.
  // eslint-disable-next-line global-require
  return require_lex(text)
}

import { lex } from './lexer.js'
function require_lex(text) {
  return lex(text)
}

function peek(state) {
  return state.tokens[state.pos] ?? null
}

function isOp(tok, text) {
  return tok !== null && tok.kind === 'op' && tok.text === text
}

function advance(state) {
  return state.tokens[state.pos++]
}

function expectOp(state, text) {
  const tok = peek(state)
  if (!isOp(tok, text)) throw new ParseError(`expected ${text}`)
  advance(state)
}

function parseComparison(state) {
  let left = parseAdditive(state)
  for (;;) {
    const tok = peek(state)
    if (tok !== null && tok.kind === 'op' && COMPARISON_OPS.has(tok.text)) {
      advance(state)
      const right = parseAdditive(state)
      left = { type: 'bin', op: tok.text, left, right }
    } else {
      break
    }
  }
  return left
}

function parseAdditive(state) {
  let left = parseMultiplicative(state)
  for (;;) {
    const tok = peek(state)
    if (isOp(tok, '+') || isOp(tok, '-')) {
      advance(state)
      const right = parseMultiplicative(state)
      left = { type: 'bin', op: tok.text, left, right }
    } else {
      break
    }
  }
  return left
}

function parseMultiplicative(state) {
  let left = parsePower(state)
  for (;;) {
    const tok = peek(state)
    if (isOp(tok, '*') || isOp(tok, '/')) {
      advance(state)
      const right = parsePower(state)
      left = { type: 'bin', op: tok.text, left, right }
    } else {
      break
    }
  }
  return left
}

function parsePower(state) {
  const base = parseUnary(state)
  if (isOp(peek(state), '^')) {
    advance(state)
    const right = parsePower(state)
    return { type: 'bin', op: '^', left: base, right }
  }
  return base
}

function parseUnary(state) {
  const tok = peek(state)
  if (isOp(tok, '+') || isOp(tok, '-')) {
    advance(state)
    const operand = parseUnary(state)
    return { type: 'unary', op: tok.text, operand }
  }
  return parsePrimary(state)
}

function parsePrimary(state) {
  const tok = peek(state)
  if (tok === null) throw new ParseError('unexpected end')

  if (tok.kind === 'num') {
    advance(state)
    return { type: 'num', value: Number(tok.text) }
  }

  if (isOp(tok, '(')) {
    advance(state)
    const inner = parseComparison(state)
    expectOp(state, ')')
    return { type: 'group', inner }
  }

  if (tok.kind === 'word') {
    advance(state)
    const upper = tok.text.toUpperCase()

    if (isOp(peek(state), '(')) {
      advance(state)
