 * Value construction, coercion, comparison, and text formatting shared by the
 * evaluator and the two print modes.
 *
 * A value is one of:
 *   { type: 'number', value: <finite number> }
 *   { type: 'text', value: <string> }
 *   { type: 'bool', value: <boolean> }
 *   { type: 'error', value: <one of the error tokens> }
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (value) => ({ type: 'number', value })
export const text = (value) => ({ type: 'text', value })
export const bool = (value) => ({ type: 'bool', value })
export const err = (value) => ({ type: 'error', value })

export const isError = (v) => v.type === 'error'

/** Wraps an arithmetic result, turning a non-finite outcome into #DIV/0!. */
export function numericResult(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

/** A value in an arithmetic position: numbers pass through, booleans become
 * 1 or 0, text becomes #VALUE!. Errors must be checked by the caller first. */
export function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return num(v.value ? 1 : 0)
  return err('#VALUE!')
}

/** A value read as an IF condition: TRUE/nonzero is true, FALSE/zero is
 * false, text is #VALUE!. Errors must be checked by the caller first. */
export function toCondition(v) {
  if (v.type === 'bool') return { ok: true, value: v.value }
  if (v.type === 'number') return { ok: true, value: v.value !== 0 }
  return { ok: false, error: err('#VALUE!') }
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/** Compares two non-error values: numbers numerically, text by code point,
 * booleans false below true, and across kinds number < text < bool. */
export function compareValues(a, b) {
  const ra = KIND_RANK[a.type]
  const rb = KIND_RANK[b.type]
  if (ra !== rb) return ra - rb
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}

/** Formats a value for `values` output. */
export function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'bool') return v.value ? 'TRUE' : 'FALSE'
  return v.value
}

/** Rounds to ten significant digits and prints as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}
"}

