   * not "directly a function argument", so it is always #ERR!. */
  evaluateNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'group':
        return this.evaluateNode(node.inner)
      case 'range':
        return err('#ERR!')
      case 'address':
        return this.evaluateAddress(node.raw)
      case 'unary':
        return this.evaluateUnary(node)
      case 'bin':
        return this.evaluateBin(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evaluateAddress(raw) {
    const parsed = parseAddress(raw)
    if (!parsed) return err('#REF!')
    return this.evaluateAt(parsed.col, parsed.row)
  }

  evaluateUnary(node) {
    const v = this.evaluateNode(node.operand)
    if (isError(v)) return v
    const n = toNumber(v)
    if (isError(n)) return n
    const result = node.op === '-' ? -n.value : n.value
    return numericResult(result)
  }

  evaluateBin(node) {
    const COMPARISON = new Set(['=', '<>', '<', '<=', '>', '>='])
    const left = this.evaluateNode(node.left)
    if (isError(left)) return left

    if (COMPARISON.has(node.op)) {
      const right = this.evaluateNode(node.right)
      if (isError(right)) return right
      const cmp = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(cmp === 0)
        case '<>':
          return bool(cmp !== 0)
        case '<':
          return bool(cmp < 0)
        case '<=':
          return bool(cmp <= 0)
        case '>':
          return bool(cmp > 0)
        case '>=':
          return bool(cmp >= 0)
      }
    }

    const ln = toNumber(left)
    if (isError(ln)) return ln
    const right = this.evaluateNode(node.right)
    if (isError(right)) return right
    const rn = toNumber(right)
    if (isError(rn)) return rn

    switch (node.op) {
      case '+':
        return numericResult(ln.value + rn.value)
      case '-':
        return numericResult(ln.value - rn.value)
      case '*':
        return numericResult(ln.value * rn.value)
      case '/':
        return rn.value === 0 ? err('#DIV/0!') : numericResult(ln.value / rn.value)
      case '^':
        return numericResult(Math.pow(ln.value, rn.value))
      default:
        throw new Error(`unknown operator ${node.op}`)
    }
  }

  /**
   * Splices a call's syntactic arguments into a flat list of items: a range
   * argument contributes one item per covered cell (ascending column, then
   * row), an out-of-range range contributes a single #REF! item, and any
   * other argument contributes itself. This flat count is what "wrong number
   * of arguments" is checked against, computed without evaluating any cell.
   */
  flattenArgs(args) {
    const items = []
    for (const arg of args) {
      if (arg.type === 'range') {
        const from = parseAddress(arg.left.raw)
        const to = parseAddress(arg.right.raw)
        if (!from || !to) {
          items.push({ kind: 'staticError', value: '#REF!' })
          continue
        }
        const colLo = Math.min(from.col, to.col)
        const colHi = Math.max(from.col, to.col)
        const rowLo = Math.min(from.row, to.row)
        const rowHi = Math.max(from.row, to.row)
        for (let col = colLo; col <= colHi; col++) {
          for (let row = rowLo; row <= rowHi; row++) {
            items.push({ kind: 'addr', col, row })
          }
        }
      } else {
        items.push({ kind: 'node', node: arg })
      }
    }
    return items
  }

  resolveItem(item) {
    if (item.kind === 'staticError') return err(item.value)
    if (item.kind === 'addr') return this.evaluateAt(item.col, item.row)
    return this.evaluateNode(item.node)
  }

  evaluateCall(node) {
    const { name, args } = node
    const isAggregate = AGGREGATE_FUNCTIONS.has(name)
    if (!isAggregate && name !== 'ABS' && name !== 'IF') return err('#NAME?')

    const items = this.flattenArgs(args)

    if (name === 'ABS') {
      if (items.length !== 1) return err('#ERR!')
      const v = this.resolveItem(items[0])
      if (isError(v)) return v
      const n = toNumber(v)
      if (isError(n)) return n
      return numericResult(Math.abs(n.value))
    }

    if (name === 'IF') {
      if (items.length !== 3) return err('#ERR!')
      const condValue = this.resolveItem(items[0])
      if (isError(condValue)) return condValue
      const cond = toCondition(condValue)
      if (!cond.ok) return cond.error
      return this.resolveItem(cond.value ? items[1] : items[2])
    }

    // SUM, MIN, MAX, COUNT, AVG
    if (items.length < 1) return err('#ERR!')

    if (name === 'COUNT') {
      let count = 0
      for (const item of items) {
        const v = this.resolveItem(item)
        if (isError(v)) return v
        if (v.type === 'number') count++
      }
      return num(count)
    }

    const numbers = []
    for (const item of items) {
      const v = this.resolveItem(item)
      if (isError(v)) return v
      const n = toNumber(v)
      if (isError(n)) return n
      numbers.push(n.value)
    }

    if (name === 'SUM') return numericResult(numbers.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return numericResult(Math.min(...numbers))
    if (name === 'MAX') return numericResult(Math.max(...numbers))
    if (name === 'AVG') return numericResult(numbers.reduce((a, b) => a + b, 0) / numbers.length)
    throw new Error(`unhandled function ${name}`)
  }

  /**
   * Every distinct cell a formula names directly (ranges expanded), ordered
   * by column then row. Purely structural: it does not depend on whether the
   * formula evaluates cleanly, only on whether it parsed.
   */
  deps(addr) {
    const cell = this.cells.get(addr)
    if (!cell || cell.kind !== 'formula' || !cell.ast) return []
    const seen = new Map()
    this.collectDeps(cell.ast, seen)
    return [...seen.values()]
      .sort((a, b) => a.col - b.col || a.row - b.row)
      .map((a) => formatAddress(a.col, a.row))
  }

  collectDeps(node, seen) {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'group':
        return this.collectDeps(node.inner, seen)
      case 'address': {
        const parsed = parseAddress(node.raw)
        if (parsed) seen.set(`${parsed.col},${parsed.row}`, parsed)
        return
      }
      case 'range': {
        const from = parseAddress(node.left.raw)
        const to = parseAddress(node.right.raw)
        if (!from || !to) return
        const colLo = Math.min(from.col, to.col)
        const colHi = Math.max(from.col, to.col)
        const rowLo = Math.min(from.row, to.row)
        const rowHi = Math.max(from.row, to.row)
        for (let col = colLo; col <= colHi; col++) {
          for (let row = rowLo; row <= rowHi; row++) {
            seen.set(`${col},${row}`, { col, row })
          }
        }
        return
      }
      case 'unary':
        return this.collectDeps(node.operand, seen)
      case 'bin':
        this.collectDeps(node.left, seen)
        this.collectDeps(node.right, seen)
        return
      case 'call':
        for (const arg of node.args) this.collectDeps(arg, seen)
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }
}
"}

