{"file_path":"src/sheetParser.js","content":"/**
 * Parses the sheet text format described in the task: one declaration per
 * line, blank and comment lines ignored, an address followed by verbatim
 * content.
 */

import { parseAddress } from './address.js'

class SheetError extends Error {}

/**
 * Parses sheet text into an ordered array of { addr, col, row, content }.
 * Throws SheetError with a ready-to-print message on the first bad line.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const declarations = []
  const seen = new Set()

  lines.forEach((rawLine, index) => {
    const lineNumber = index + 1
    const line = rawLine.replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) return

    let i = 0
    while (i < line.length && line[i] !== ' ' && line[i] !== '\t') i++
    const addrText = line.slice(0, i)
    while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
    const content = line.slice(i)

    const addr = addrText.toUpperCase()
    const parsed = parseAddress(addr)
    if (!parsed) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${addr}`)
    }
    if (seen.has(addr)) {
      throw new SheetError(`error: line ${lineNumber}: cell ${addr} is declared twice`)
    }
    seen.add(addr)
    declarations.push({ addr, col: parsed.col, row: parsed.row, content })
  })

  return declarations
}

export { SheetError }
"}

